    "en": {
      "applicationProcess": [
        {
          "mode": "Offline",
          "process": [
            {
              "children": [
                {
                  "bold": true,
                  "text": "Step 1: "
                },
                {
                  "text": "Download and fill out the application form for AICTE-Grant for Augmenting Infrastructure in North Eastern Region (GAINER)."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "bold": true,
                  "text": "Step 2: "
                },
                {
                  "text": "Verify that every page of the application form has the signature and stamp of the Head of the Institute."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "bold": true,
                  "text": "Step 3: "
                },
                {
                  "text": "Attach all the essential documents along with the filled application form."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "bold": true,
                  "text": "Step 4: "
                },
                {
                  "text": "Kindly ensure all the information is correct and then sent the Application form along with all the essential documents through registered post/speed post to:"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "Advisor,"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "Institutional Development Cell,"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "All India Council for Technical Education,"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "Nelson Mandela Marg, Vasant Kunj,"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "New Delhi-110070"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "bold": true,
                  "text": "Processing of Proposals"
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "a. Submission of application by the institute. "
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "b. Screening/ scrutiny of applications at Council. "
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "c. Evaluation of applications by the expert committee. "
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "d. The final decision will be taken by the Council, keeping in view the recommendations made by the experts and the availability of funds for the scheme. "
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": "e. After the Council\u2019s approval, the Sanction Letter and the first installment of funds for the Project will be sent to the institution. "
                }
              ],
              "type": "paragraph"
            }
          ],
          "process_md": "**Step 1:** Download and fill out the application form for AICTE-Grant for Augmenting Infrastructure in North Eastern Region (GAINER).\n**Step 2:** Verify that every page of the application form has the signature and stamp of the Head of the Institute.\n**Step 3:** Attach all the essential documents along with the filled application form.\n**Step 4:** Kindly ensure all the information is correct and then sent the Application form along with all the essential documents through registered post/speed post to:\nAdvisor,\nInstitutional Development Cell,\nAll India Council for Technical Education,\nNelson Mandela Marg, Vasant Kunj,\nNew Delhi-110070\n<br>\n\n**Processing of Proposals**\na. Submission of application by the institute. \nb. Screening/ scrutiny of applications at Council. \nc. Evaluation of applications by the expert committee. \nd. The final decision will be taken by the Council, keeping in view the recommendations made by the experts and the availability of funds for the scheme. \ne. After the Council\u2019s approval, the Sanction Letter and the first installment of funds for the Project will be sent to the institution. \n",
          "url": ""
        }
