              {
                "children": [
                  {
                    "text": "All Capital Cities/Towns of States/ UTs, not covered in above ,"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "All  Cities/  Towns  classified  as  Heritage  Cities  by  MoHUA  under  the  HRIDAY Scheme,"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Thirteen Cities and Towns on the stem of the main rivers with a population above 75,000 and less than 1 lakh, and"
                  }
                ],
