                    "bold": true,
                    "text": ""
                  }
                ],
                "type": "paragraph"
              },
              {
                "children": [
                  {
                    "bold": true,
                    "text": "Objectives:"
                  }
                ],
                "type": "paragraph"
              },
              {
                "children": [
                  {
                    "children": [
                      {
                        "text": "To understand the Scheme of Fund for Regeneration of Traditional Industries (SFURTI)."
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "To train the students and faculty in identifying and presenting a project proposal."
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "To enhance and sharpen their skills to develop a viable detailed project report."
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "To understand resource management for building a project with technological and social innovations."
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "To develop an in depth understanding of project management, resolve challenges faced in sustainable rural economic development and derive lessons on social, economic and environmental impacts."
