    "en": {
      "applicationProcess": [
        {
          "mode": "Online",
          "process": [
            {
              "children": [
                {
                  "bold": true,
                  "italic": true,
                  "text": "Step 1: Survey and Notification",
                  "underline": true
                }
              ],
              "type": "heading_five"
            },
            {
              "children": [
                {
                  "children": [
                    {
                      "text": "The State/Union Territory Government must first conduct a district-wise survey of existing homes and upload the details of Gap Districts or Districts of having insufficient capacity onto the "
                    },
                    {
                      "children": [
                        {
                          "text": "E-anudaan Portal."
                        }
                      ],
                      "link": "https://grants-msje.gov.in/",
                      "type": "link"
                    },
                    {
                      "text": ""
                    }
                  ],
                  "type": "list_item"
                },
                {
                  "children": [
                    {
                      "text": "If the State/Union Territory Government records that it is unable to establish the Home on its own, the Central Government publishes an open notification inviting applications with wide publicity."
                    }
                  ],
                  "type": "list_item"
                }
              ],
              "type": "ul_list"
            },
            {
              "children": [
                {
                  "bold": true,
                  "italic": true,
                  "text": "Step 2: Submission of Proposal",
                  "underline": true
                }
              ],
              "type": "heading_five"
            },
            {
              "children": [
                {
                  "children": [
                    {
                      "bold": true,
                      "text": "New Proposals:",
                      "underline": true
                    },
                    {
                      "text": " All fresh proposals for project sanction must be submitted online on the E-anudaan portal in the prescribed proforma along with relevant documents within the stipulated timeline."
                    }
                  ],
                  "type": "list_item"
                },
                {
                  "children": [
                    {
                      "bold": true,
                      "text": "On-going/Renewal Proposals:",
                      "underline": true
                    },
                    {
                      "text": " Applications for the release of grants must be made in the prescribed proforma along with relevant documents and the Utilization Certificate of expenditure from the previous Financial Year before April 30th each year."
                    }
                  ],
                  "type": "list_item"
                }
              ],
              "type": "ul_list"
            },
            {
              "children": [
                {
                  "bold": true,
                  "italic": true,
                  "text": "Step 3: Verification and Approval",
                  "underline": true
                }
              ],
              "type": "heading_five"
            },
            {
              "children": [
                {
                  "children": [
                    {
                      "bold": true,
                      "text": "District Level Authentication:",
                      "underline": true
                    },
                    {
                      "text": " Once uploaded, the proposal is made available to the Central Ministry and the District Administration/State Government level for examination. The District Collector (or representative) is required to authenticate all certificates submitted by the applicant."
