                  ],
                  "type": "list_item"
                },
                {
                  "children": [
                    {
                      "bold": true,
                      "text": "Recommendation:",
                      "underline": true
                    },
                    {
                      "text": " District Administration/State Government shall recommend New/Fresh proposals, along with Inspection reports, by June 15th each year."
