        "eligibilityDescription": [
          {
            "children": [
              {
                "bold": true,
                "text": "Eligibility Criteria for Applicants - "
              }
            ],
            "type": "block_quote"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "The applicant should be an Indian national."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should belong to OBCs, as notified by their State Govt./ UT Admn."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should be pursuing post-matriculation or post-secondary courses in a recognized institution."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should be permanently settled and should have passed a recognized Matriculation or Higher Secondary or any higher examination."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should be eligible if, after failing or passing the undergraduate/Post-Graduate examinations in Arts/Science/Commerce, they join any recognized professional or technical certificate/diploma/degree courses, provided they are otherwise eligible. No subsequent failure will be condoned, except for courses in Group 'A', and no further change in the course will be allowed."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The employed applicant should be eligible to the extent of reimbursement of all compulsorily payable non-refundable fees if their income, combined with the income of their parents/guardians, does not exceed Rs. 1.50 lakh per annum."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The unemployed applicant should be eligible if their parents/guardians' income from all sources does not exceed Rs. 1.50 lakh per annum."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The scholarships are restricted to two boys of the same parents/guardian, with this restriction not applying to girls."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "The applicant should be eligible to pursue post-graduate courses in medicine only if they are not allowed to practice during the period of their course."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should not hold any other scholarship/stipend concurrently under this Scheme. If awarded any other scholarship/stipend, they can exercise their option for either of the two scholarships/stipends, whichever is more beneficial to them, and should inform the awarding authority through the Head of the Institution about the option made. No scholarship will be paid from the date they accept any other scholarship/stipend. However, students can accept free lodging or a grant or ad-hoc monetary help from the State Government or any other source for the purchase of books, equipment, or for meeting the expenses on board and lodging, in addition to the scholarship amount paid under the Scheme."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The applicant should be eligible if they pursue their studies through correspondence courses, with eligibility only towards reimbursement of a non-refundable fee and an annual allowance of Rs. 900/- for essential/prescribed books, as applicable."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
