      "eligibilityCriteria": {
        "eligibilityDescription": [
          {
            "children": [
              {
                "children": [
                  {
                    "text": "SHGs should be in active existence at least for the last 6 months as per the books of account of SHGs and not from the date of opening of the S/B account."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "SHGs should be practicing \u2018Panchasutras\u2019 i.e., Regular meetings; Regular savings; Regular inter-loaning; Timely repayment; and Up-to-date books of accounts."
