              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Assistance is processed quickly at RCC level due to revolving funds.\n<br>\n\n",
          "question": "How long does it take to receive assistance?"
