        "eligibilityDescription_md": "\n1. The applicant must be at least 18 years of age.\n1. The applicant must be residing in a Rural Area.\n\n"
      },
      "schemeContent": {
        "benefitTypes": {
          "label": "Cash",
          "value": "Cash"
        },
        "benefits": [
          {
            "children": [
              {
                "children": [
                  {
                    "text": "The applicant receives guaranteed employment within 15 days from the date of application."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Work is to be provided within a radius of 5 kilometers of the applicant\u2019s residence if possible, and in any case within the Block. If the applicant lives more than 5 km away from the worksite, he/she will be entitled to a travel and subsistence allowance (10% of the minimum wage)."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Wages are paid within a week, or fifteen days at most. Men and Women are paid equally."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Shade, drinking water, and first-aid are provided at every worksite."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ol_list"
          },
          {
            "children": [
              {
                "text": ""
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "text": "Exclusive measures for the promotion of the participation of the disabled persons:"
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "Identification of suitable works"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Mobilization of disabled persons by focussing on awareness and special provisions"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Specifically identified works for disabled persons in the case of large GPs"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Preference to appoint as mates and as workers for providing drinking water, to manage cr\u00e8ches, etc., at the worksites"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Adoption of tools and equipment/facilities at workplaces"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Treating persons with disabilities with respect"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Special drive to ensure 100 days of employment to such households"
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Provide a special job card of a distinct color"
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ol_list"
          },
          {
            "children": [
              {
                "text": ""
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "text": "Specific attention and provisions for Senior Citizens: "
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "Exclusive senior citizen groups may be formed and special works which require lesser physical effort are identified and allotted to these groups."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ol_list"
          },
          {
            "children": [
              {
                "text": ""
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "text": "Specific attention and provisions for Internally Displaced Persons:"
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "A special job card to be provided will be valid till these families are displaced and will lose its validity as soon as they return to their original place of residence."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ol_list"
          }
        ],
        "benefits_md": "\n1. The applicant receives guaranteed employment within 15 days from the date of application.\n1. Work is to be provided within a radius of 5 kilometers of the applicant\u2019s residence if possible, and in any case within the Block. If the applicant lives more than 5 km away from the worksite, he/she will be entitled to a travel and subsistence allowance (10% of the minimum wage).\n1. Wages are paid within a week, or fifteen days at most. Men and Women are paid equally.\n1. Shade, drinking water, and first-aid are provided at every worksite.\n\n<br>\n\n**Exclusive measures for the promotion of the participation of the disabled persons:**\n\n1. Identification of suitable works\n1. Mobilization of disabled persons by focussing on awareness and special provisions\n1. Specifically identified works for disabled persons in the case of large GPs\n1. Preference to appoint as mates and as workers for providing drinking water, to manage cr\u00e8ches, etc., at the worksites\n1. Adoption of tools and equipment/facilities at workplaces\n1. Treating persons with disabilities with respect\n1. Special drive to ensure 100 days of employment to such households\n1. Provide a special job card of a distinct color\n\n<br>\n\n**Specific attention and provisions for Senior Citizens:** \n\n1. Exclusive senior citizen groups may be formed and special works which require lesser physical effort are identified and allotted to these groups.\n\n<br>\n\n**Specific attention and provisions for Internally Displaced Persons:**\n\n1. A special job card to be provided will be valid till these families are displaced and will lose its validity as soon as they return to their original place of residence.\n\n",
        "briefDescription": "An employment scheme by the MoRD, providing provide at least 100 days of guaranteed wage employment in a financial year to every rural household whose adult members volunteer to do unskilled work. Any Indian citizen above the age of 18 years and residing in a rural area can apply to this scheme.",
        "detailedDescription": [
          {
            "children": [
              {
                "text": "An employment scheme by the Ministry of Rural Development, providing provide at least 100 days of guaranteed wage employment in a financial year to every rural household whose adult members volunteer to do unskilled work. Any Indian citizen above the age of 18 years and residing in a rural area can apply to this scheme. The applicant receives guaranteed employment within 15 days from the date of application."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "text": ""
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "text": "The wage is deposited directly in the Bank Account / Post Office Account of the applicant. Wages are paid within a week, or fifteen days at most. Men and Women are paid equally. MGNREGA covers the entire country with the exception of districts that have a hundred percent urban population."
              }
            ],
            "type": "paragraph"
          }
        ],
        "detailedDescription_md": "An employment scheme by the Ministry of Rural Development, providing provide at least 100 days of guaranteed wage employment in a financial year to every rural household whose adult members volunteer to do unskilled work. Any Indian citizen above the age of 18 years and residing in a rural area can apply to this scheme. The applicant receives guaranteed employment within 15 days from the date of application.\n<br>\n\nThe wage is deposited directly in the Bank Account / Post Office Account of the applicant. Wages are paid within a week, or fifteen days at most. Men and Women are paid equally. MGNREGA covers the entire country with the exception of districts that have a hundred percent urban population.\n",
        "exclusions": [
          {
            "children": [
              {
                "text": "NA"
              }
