              ],
              "type": "paragraph"
            }
          ],
          "definitions_md": "a person who has completed 18 years of age.\n",
          "name": "adult",
          "source": "https://nrega.nic.in/Circular_Archive/archive/Operational_guidelines_4thEdition_eng_2013.pdf"
        },
        {
          "definition": [
            {
              "children": [
                {
                  "text": "the members of a family related to each other by blood, marriage or adoption and normally residing together and sharing meals or holding a common ration card."
                }
              ],
              "type": "paragraph"
            }
          ],
          "definitions_md": "the members of a family related to each other by blood, marriage or adoption and normally residing together and sharing meals or holding a common ration card.\n",
          "name": "Household",
          "source": "https://nrega.nic.in/Circular_Archive/archive/Operational_guidelines_4thEdition_eng_2013.pdf"
        },
        {
          "definition": [
            {
              "children": [
                {
                  "text": "all remuneration, capable of being expressed in terms of money, which would, if the terms of the contract of employment, express or implied, were fulfilled, be payable to a person employed in respect of his employment or of work done in such employment, [and includes house rent allowance] but does not include:"
                }
