                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "School pass-outs (class 12th) - \u20b9 7,000/-"
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "National or State Certificate holder - \u20b9 7,000/-"
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
                        "text": "Technician (vocational) apprentice or Vocational Certificate holder or Sandwich Course (Students from Diploma Institutions) - \u20b9 7,000/-"
                      }
                    ],
                    "type": "list_item"
                  },
                  {
                    "children": [
                      {
