    "en": {
      "faqs": [
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Release of Central and States\u2019 share for this scheme will be through PFMS system. Both the GoI and State share of funds shall be transferred through defined mechanism of PFMS. "
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Release of Central and States\u2019 share for this scheme will be through PFMS system. Both the GoI and State share of funds shall be transferred through defined mechanism of PFMS. \n",
          "question": "What is the fund flow mechanism for the scheme?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "The State Governments may develop a sound mechanism for involvement of PRIs in the formulation, prioritization of activities & identification of beneficiaries at grass root level and ensure involvement of NGOs, Self Help Groups and Private companies for selection of beneficiary, identification and mapping of priority areas, liaising with processors, state officials and SAUs, etc."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "The State Governments may develop a sound mechanism for involvement of PRIs in the formulation, prioritization of activities &amp; identification of beneficiaries at grass root level and ensure involvement of NGOs, Self Help Groups and Private companies for selection of beneficiary, identification and mapping of priority areas, liaising with processors, state officials and SAUs, etc.\n",
          "question": "Is there a role of Panchayati Raj Institutions (PRIs) under the scheme?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "The processors are eligible for setting up of seed gardens and nurseries, distribution of planting material etc. The processors will submit their oil palm area expansion target and component wise Annual Action Plan (AAP) to the State for its implementation in the state."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "The processors are eligible for setting up of seed gardens and nurseries, distribution of planting material etc. The processors will submit their oil palm area expansion target and component wise Annual Action Plan (AAP) to the State for its implementation in the state.\n",
          "question": "What is the role of processors in the Mission?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Any farmer who owns the land can avail benefits under the scheme."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Any farmer who owns the land can avail benefits under the scheme.\n",
          "question": "Is there any age criteria for availing scheme benefits?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "All farmers are to be considered under the scheme, however, the resources for Schedule Caste (17%) and Schedule Tribe (8%) will be earmarked for utilization under all the components of NMEO."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "All farmers are to be considered under the scheme, however, the resources for Schedule Caste (17%) and Schedule Tribe (8%) will be earmarked for utilization under all the components of NMEO.\n",
          "question": "Is there a preference for certain gender /caste of farmers?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "No area restriction is applicable for individual farmers for availing subsidy/ intervention. "
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "No area restriction is applicable for individual farmers for availing subsidy/ intervention. \n",
          "question": "Is there an area restriction?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Yes, financial assistance is available for nutrient management and pest management practices to ensure healthy crop growth."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Yes, financial assistance is available for nutrient management and pest management practices to ensure healthy crop growth.\n<br>\n\n",
          "question": "Are farmers provided assistance for nutrient and pest management?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Yes, assistance is provided for various farm implements, machinery, harvesting technologies, and other interventions related to oil palm cultivation."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Yes, assistance is provided for various farm implements, machinery, harvesting technologies, and other interventions related to oil palm cultivation.\n<br>\n\n",
          "question": "Does the scheme support the purchase of farm equipment?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Yes, the scheme includes capacity-building activities, training programs, and extension services to promote improved cultivation practices."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Yes, the scheme includes capacity-building activities, training programs, and extension services to promote improved cultivation practices.\n<br>\n\n",
          "question": "Is training provided to oil palm farmers under the scheme?"
        }
      ]
    },
    "schemeId": "651267fe7846de4ead1d889b"
  }
}

