        "eligibilityDescription_md": "\n- The applicant must be a Laghu Vyapari, self-employed person, shop owner, retail trader, rice mill owner, oil mill owner, workshop owner, commission agent, real estate broker, small hotel owner, or restaurant owner.\n- The applicant must be between 18 and 40 years of age.\n- The applicant must have an annual turnover that does not exceed \u20b91,50,00,000/-.\n- The applicant must possess a savings bank account in their name.\n- The applicant must possess an Aadhaar Card or Aadhaar Number.\n\n<br>\n\n"
      },
      "schemeContent": {
        "benefitTypes": {
          "label": "Cash",
          "value": "Cash"
        },
        "benefits": [
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "1. Pension Benefit",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "align": "justify",
                "children": [
                  {
                    "text": "Each eligible subscriber under this scheme shall receive an assured minimum monthly pension of \u20b93,000/- after attaining the age of sixty years."
                  }
                ],
                "type": "list_item"
              },
              {
                "align": "justify",
                "children": [
                  {
                    "text": "The Government of India will make a matching contribution into the subscriber's pension account every month as a subsidy."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "2. Family Pension on Death of Beneficiary",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "align": "justify",
            "children": [
              {
                "text": "During the receipt of the pension, if an eligible beneficiary dies, the spouse shall be entitled to receive fifty per cent of the pension received by such beneficiary as a family pension, which is applicable only to the spouse."
              }
            ],
            "type": "paragraph"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "3. Provisions for Permanent Disablement Before Age of Sixty",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "align": "justify",
                "children": [
                  {
                    "text": "If an eligible beneficiary has given regular contributions and becomes permanently disabled before attaining the age of sixty years, the spouse shall be entitled to continue with the scheme by payment of regular contributions. "
                  }
                ],
                "type": "list_item"
              },
              {
                "align": "justify",
                "children": [
                  {
                    "text": "In case of permanent disablement where the spouse does not continue, they can exit the scheme by receiving the share of contribution deposited by the subscriber, with interest as actually earned thereon by the Pension Fund or the savings bank interest rate, whichever is higher."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "4. Exit Before Completion of Ten Years",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "align": "justify",
            "children": [
              {
                "text": "In case an eligible beneficiary exits this scheme within a period of less than ten years from the date of joining, the share of contribution by them only will be returned with the savings bank rate of interest payable thereon."
              }
            ],
            "type": "paragraph"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "5. Exit After Ten Years but Before Age of Sixty",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "align": "justify",
            "children": [
              {
                "text": "If an eligible beneficiary exits after completion of a period of ten years or more from the date of joining but before the age of sixty years, their share of contribution only shall be returned along with accumulated interest thereon as actually earned by the Pension Fund or the savings bank interest rate, whichever is higher."
              }
            ],
            "type": "paragraph"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "6. Death of Beneficiary During the Contribution Period",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "align": "justify",
                "children": [
                  {
                    "text": "If an eligible beneficiary has given regular contributions and dies due to any cause, the spouse shall be entitled to continue with the scheme by payment of regular contributions. "
                  }
                ],
                "type": "list_item"
              },
              {
                "align": "justify",
                "children": [
                  {
                    "text": "If the spouse does not wish to continue after the beneficiary's death, they can exit by receiving the share of contribution paid by the beneficiary along with accumulated interest, as actually earned by the Pension Fund or at the savings bank interest rate, whichever is higher."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "align": "justify",
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "7. Corpus Reversion After Death of Both Beneficiary and Spouse",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "align": "justify",
            "children": [
              {
                "text": "After the death of the beneficiary and his or her spouse, the corpus shall be credited back to the fund."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "text": ""
              }
            ],
            "type": "paragraph"
