        "benefits": [
          {
            "children": [
              {
                "children": [
                  {
                    "text": "A "
                  },
                  {
                    "bold": true,
                    "text": "minimum assured pension of \u20b93,000/- per month",
                    "underline": true
                  },
                  {
                    "text": " is provided to the subscriber after attaining the age of 60 years."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "A matching contribution is provided by the Central Government on a 50:50 basis, where an equal amount to the subscriber's age-specific contribution (ranging from \u20b955/- to \u20b9200/-) is credited to the pension account."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "children": [
              {
                "text": ""
