            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "*   During the receipt of the pension, if the subscriber dies:"
              },
              {
                "text": " The spouse of the beneficiary shall be entitled to receive a family pension equal to 50% of the pension received by the beneficiary."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "*   If a beneficiary has given regular contributions and died due to any cause before the age of 60 years: "
              },
              {
                "italic": true,
                "text": "Their spouse will be entitled to join and continue the scheme subsequently by the payment of regular contributions."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "*   If a beneficiary has given regular contributions and died due to any cause before the age of 60 years, and the spouse decides to exit: "
              },
              {
                "italic": true,
                "text": "The beneficiary's contribution along with accumulated interest as actually earned by the fund or at the savings bank interest rate (whichever is higher) will be returned."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "*   If the subscriber exits the scheme within a period of less than 10 years: "
              },
              {
                "italic": true,
                "text": "The beneficiary's share of contribution only will be returned to them with the savings bank interest rate."
              }
            ],
            "type": "paragraph"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "*   If the subscriber exits after a period of 10 years or more but before the superannuation age of 60 years: "
              },
              {
                "italic": true,
                "text": "The beneficiary's share of contribution along with accumulated interest as actually earned by the fund or at the savings bank interest rate, whichever is higher, will be returned."
              }
