  "faqs": {
    "_id": "62ac6779f3185b4e75008a1b",
    "en": {
      "faqs": [
        {
          "answer": [
            {
              "children": [
                {
                  "text": "This accident insurance scheme covers; Loss of life due to COVID19, and Accidental death on account of COVID-19 related duty.\n"
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "This accident insurance scheme covers; Loss of life due to COVID19, and Accidental death on account of COVID-19 related duty.\n\n",
          "question": "What does this Scheme cover?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "An accident is sudden, unforeseen and involuntary event caused by external, visible and violent means."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "An accident is sudden, unforeseen and involuntary event caused by external, visible and violent means.\n",
          "question": "What is the definition of Accident?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "1. Public healthcare providers including community health workers, who may have to be in direct contact and care of COVID-19 patients and who may be at risk of being impacted by this. \n2. Private hospital staff and retired /volunteer /local urban bodies/ contracted /daily wage/ad-hoc/outsourced staff requisitioned by States/ Central hospitals/ autonomous hospitals of Central/ States/UTs, AIIMS and INIs/ hospital of Central Ministries can also be drafted for COVID 19 related responsibilities."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "1. Public healthcare providers including community health workers, who may have to be in direct contact and care of COVID-19 patients and who may be at risk of being impacted by this. \n2. Private hospital staff and retired /volunteer /local urban bodies/ contracted /daily wage/ad-hoc/outsourced staff requisitioned by States/ Central hospitals/ autonomous hospitals of Central/ States/UTs, AIIMS and INIs/ hospital of Central Ministries can also be drafted for COVID 19 related responsibilities.\n",
          "question": "Who all are covered under the scheme?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Volunteers are those who are drafted by the Government Official authorized by Central/State/ UT Government for care and may have come in direct contact of the COVID-19 patient"
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Volunteers are those who are drafted by the Government Official authorized by Central/State/ UT Government for care and may have come in direct contact of the COVID-19 patient\n",
          "question": "Who can be a volunteer under this scheme? "
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Private persons are those who are engaged by both public & private health care institutions/organization through an agency and were deployed /drafted for care and may have come in direct contact of the COVID-19 patient (with the proof that the service of the agencies were engaged by the institution/organization). "
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Private persons are those who are engaged by both public & private health care institutions/organization through an agency and were deployed /drafted for care and may have come in direct contact of the COVID-19 patient (with the proof that the service of the agencies were engaged by the institution/organization). \n",
          "question": "Who are \u2018Private persons\u2019 under this scheme? "
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "The duration of the policy is for a period of 90 days, starting from March 30, 2020."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "The duration of the policy is for a period of 90 days, starting from March 30, 2020.\n",
          "question": "When does insurance coverage policy begins and ends? "
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "There\u2019s no age limit for this scheme."
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "There's no age limit for this scheme.\n",
          "question": "Is there any age-limit for health workers under this scheme? "
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Individual enrolment is not required.\n"
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "Individual enrolment is not required.\n\n",
          "question": "Is individual enrolment required?"
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "The entire amount of premium for this scheme is being borne by the Ministry of Health and Family Welfare, Government of India. \n"
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "The entire amount of premium for this scheme is being borne by the Ministry of Health and Family Welfare, Government of India. \n\n",
          "question": "Whether an individual is required to pay any premium to be eligible under the scheme? "
        },
        {
          "answer": [
            {
              "children": [
                {
                  "text": "INR 50,00,000/- will be paid to the claimant of the insured person"
                }
              ],
              "type": "paragraph"
            }
          ],
          "answer_md": "INR 50,00,000/- will be paid to the claimant of the insured person\n",
          "question": "What is the benefit available to the insured persons?"
        }
      ]
    },
