        "benefits": [
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "Stipend Package",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "The Fellow shall be entitled to a consolidated stipend package of \u20b950,000/- (Rupees Fifty thousand only) per month during the orientation period."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The Fellow shall be entitled to \u20b975,000/- (Rupees Seventy Five Thousand only) per month during the first year of the Fellowship (post-orientation)."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The Fellow shall receive a 10% increment during the second year, subject to satisfactory performance."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "This package is deemed to cover the Fellow\u2019s honorarium, boarding and lodging expenses during orientation, accommodation/house rent during the rest of the Fellowship period, health insurance, life and disability insurance cover, and any other contingency expenses."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Travel reimbursement will be based on actual costs and restricted to AC-II tier train fare by the shortest route or equivalent, plus local transport cost. Women Fellows with children below five years are allowed the travel cost of a care-giver if the care-giver accompanies the Fellow with her child."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "Other Benefits",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "Participation in a post graduate degree programme through distance learning and contact sessions leading to a post graduate degree in Development Practice."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Award of a Fellowship Certificate and an appropriate post graduate degree in Development Practice upon satisfactory completion of engagement and course requirements."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Office facilities made available by the District Collector, including suitable space, a computer/laptop, and internet connectivity free of charge."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Provision of suitable modes of transport by District administration while travelling within the district for regular work."
                  }
                ],
                "type": "list_item"
              }
            ],
            "type": "ul_list"
          },
          {
            "children": [
              {
                "bold": true,
                "italic": true,
                "text": "Disbursement of Stipend",
                "underline": true
              }
            ],
            "type": "heading_five"
          },
          {
            "children": [
              {
                "children": [
                  {
                    "text": "During the orientation programme, the stipend shall be paid by the National Rural Livelihood Promotion Society through the Programme Mentor."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "Post-placement, the National Rural Livelihood Promotion Society shall pay the monthly stipend to the Fellows by providing budgetary support to the State Rural Livelihood Mission society."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The State Rural Livelihood Mission society shall make direct deposits into the bank account of each Fellow immediately upon confirming the attendance of the Fellow from the District Collector at the end of the month."
                  }
                ],
                "type": "list_item"
              },
              {
                "children": [
                  {
                    "text": "The second-year increment is subject to the Fellow\u2019s satisfactory performance as determined by the National Rural Livelihood Promotion Society in consultation with the Programme Mentor."
