      "faqs": [
        {
          "answer": [
            {
              "children": [
                {
                  "text": "Establishments with pending inquiries under Sections 7A, 7B, or 7C of the Employees' Provident Funds and Miscellaneous Provisions Act, 1952, will not be provided with any employer incentives until cleared."
                }
              ],
              "type": "paragraph"
            },
            {
              "children": [
                {
                  "text": ""
